-- ============================================================
-- 142 · Variantele capitolelor: london-system, kings-gambit, queens-gambit, catalan-opening, ruy-lopez, english-opening, kings-indian-attack, colle-system, vienna-game, sicilian-defense, french-defense, caro-kann-defense, kings-indian-defense, nimzo-indian-defense, dutch-defense, slav-defense, pirc-defense, scandinavian-defense, alekhine-defense
--
-- Ca la Italiana (migrările 138 şi 141), cerut pe 2026-11-25:
--  * variante = ramificaţiile în care adversarul face altă mutare în cel puţin
--    10% din partidele de 1000–1600 (Chess.com, rapid şi blitz), nu sub 4% la
--    400–1000 şi 1600–2300; cel mult 3 pe capitol, după câte partide ajung acolo.
--    Continuarea: adversarul joacă mutarea cea mai frecventă la 1000–1600; tu,
--    cea mai jucată la 1600–2300 dintre cele la cel mult 0,35 de motor
--    (Stockfish, adâncime 18). 7 semi-mutări după despărţire.
--  * grup = mutarea adversarului de la care porneşte capitolul;
--  * popularitate_pe_rating (capitol şi variante): Chess.com 400/700/1000/1300/
--    1600/1900, Lichess 400/1000/1200/1400/1600/1800/2000/2200; trepte cu sub
--    100 de partide lăsate goale.
-- ============================================================

update public.opening_lines l set grup = '1…d5', popularitate_pe_rating = '{"chesscom":{"400":54,"700":54.8,"1000":52.8,"1300":48.8,"1600":41.8,"1900":35.9},"lichess":{"400":55.4,"1000":56.2,"1200":53.9,"1400":50.3,"1600":46,"1800":40.1,"2000":32.6,"2200":27.9}}'::jsonb,
  variante = $j$[{"nume":"Dacă adversarul joacă 2…Cc6","moves_uci":"d2d4 d7d5 g1f3 b8c6 c1f4 g8f6 e2e3 c8g4 f1e2 e7e6 b1d2","move_explanations":{"3":"Cc6 — adversarul scoate calul pe c6, în faţa pionului de pe c7. E o mutare comodă, dar pionul c nu mai poate lovi în centru cu c5.","4":"Nf4 — nebunul iese pe f4 înainte să închizi drumul cu e3. Ăsta e semnul sistemului London.","5":"Cf6 — adversarul scoate şi celălalt cal.","6":"e3 — întăreşti pionul de pe d4 şi deschizi drumul nebunului de pe f1.","7":"Ng4 — nebunul adversarului leagă calul de pe f3 de damă.","8":"Ne2 — dezlegi calul: dacă nebunul ia pe f3, iei înapoi cu nebunul, iar dama rămâne pe loc.","9":"e6 — adversarul deschide drumul nebunului de pe f8.","10":"Cbd2 — scoţi al doilea cal, care sprijină calul de pe f3."},"final_text":"Ai scos aproape toate piesele, iar pionii de pe d4 şi e3 ţin centrul. Urmează rocada, apoi c3 sau Ce5.","popularitate_pe_rating":{"chesscom":{"400":37.3,"700":34.1,"1000":27.9,"1300":21.3,"1600":13.5,"1900":9},"lichess":{"400":38.3,"1000":38,"1200":34.3,"1400":28.2,"1600":21.2,"1800":14.1,"2000":7.8,"2200":4.4}}},{"nume":"Dacă adversarul joacă 2…e6","moves_uci":"d2d4 d7d5 g1f3 e7e6 c1f4 f8d6 f4g3 d6g3 h2g3 g8f6 e2e3","move_explanations":{"3":"e6 — adversarul deschide drumul nebunului de pe f8, dar îl închide pe cel de pe c8.","4":"Nf4 — nebunul iese înainte de e3, ca să nu rămână închis în spatele pionilor.","5":"Nd6 — adversarul îşi pune nebunul în faţa celui al tău şi îţi propune schimbul.","6":"Ng3 — păstrezi nebunul pe diagonală. Dacă adversarul ia pe g3, iei cu pionul de pe h2.","7":"Nxg3 — adversarul schimbă nebunii.","8":"hxg3 — iei înapoi cu pionul h. Coloana h se deschide, iar tura ta de pe h1 ţinteşte acum pionul de pe h7.","9":"Cf6 — adversarul scoate calul, care apără încă o dată pionul de pe h7.","10":"e3 — deschizi drumul nebunului de pe f1."},"final_text":"Nebunii de câmpuri negre s-au schimbat, iar coloana h îi rămâne turei tale. Scoate nebunul pe d3 şi calul pe d2; rocada o poţi lăsa pentru mai târziu.","popularitate_pe_rating":{"chesscom":{"400":12.8,"700":13.8,"1000":15.9,"1300":17.7,"1600":18.4,"1900":17.8},"lichess":{"400":12.8,"1000":13,"1200":14.2,"1400":15.8,"1600":17.3,"1800":17.4,"2000":16.6,"2200":15.3}}},{"nume":"Dacă adversarul joacă 4…Nd6","moves_uci":"d2d4 d7d5 g1f3 g8f6 c1f4 e7e6 e2e3 f8d6 f4g3 e8g8 b1d2 c7c5 c2c3 b8c6 f1d3","move_explanations":{"7":"Nd6 — în loc de Ne7, adversarul pune nebunul pe d6, în faţa celui al tău, şi îţi propune schimbul.","8":"Ng3 — nu schimbi tu: retragi nebunul pe g3 şi îl păstrezi pe diagonală.","9":"Rocada adversarului: îşi pune regele la adăpost.","10":"Cbd2 — scoţi calul pe d2, în spatele pionilor tăi.","11":"c5 — adversarul loveşte în pionul de pe d4.","12":"c3 — întăreşti d4 cu încă un pion. Lanţul c3–d4–e3 ţine centrul.","13":"Cc6 — adversarul scoate calul şi pune din nou presiune pe d4.","14":"Nd3 — scoţi nebunul de pe f1 spre regele adversarului."},"final_text":"Ai scos toate piesele uşoare, iar centrul e sprijinit de pionii de pe c3, d4 şi e3. Urmează rocada; planul obişnuit e Ce5, cu ochii pe regele adversarului.","popularitate_pe_rating":{"chesscom":{"400":30.9,"700":33,"1000":33.4,"1300":34.4,"1600":38.2,"1900":43.3},"lichess":{"400":27.1,"1000":30.3,"1200":31.5,"1400":32.9,"1600":35.6,"1800":40.3,"2000":47.3,"2200":55.2}}}]$j$::jsonb
  from public.courses c where c.id = l.course_id and c.slug = 'london-system' and l.variation_code = 'A';

