  variante = $j$[{"nume":"Dacă adversarul joacă 3…Cf6","moves_uci":"d2d4 g7g6 g1f3 f8g7 c1f4 g8f6 e2e3 e8g8 f1e2 d7d6 e1g1 b8d7 h2h3","move_explanations":{"5":"Cf6 — adversarul scoate întâi calul, înainte de d6.","6":"e3 — întăreşti pionul de pe d4 şi deschizi drumul nebunului de pe f1.","7":"Rocada adversarului: regele se ascunde în spatele nebunului de pe g7.","8":"Ne2 — scoţi nebunul şi pregăteşti rocada.","9":"d6 — adversarul îşi face loc pentru e5.","10":"Rocada ta. Regele e la adăpost, iar tura poate veni în centru.","11":"Cbd7 — adversarul scoate şi al doilea cal, cu gândul la e5.","12":"h3 — faci loc nebunului tău: dacă e atacat, se poate retrage pe h2."},"final_text":"Ambii regi sunt la adăpost. Pionii de pe d4 şi e3 ţin centrul, iar nebunul de pe f4 nu poate fi alungat uşor. Urmează c3 sau c4, apoi calul de pe b1 în joc.","popularitate_pe_rating":{"chesscom":{"400":28.6,"700":24.8,"1000":21.7,"1300":19.2,"1600":15.7,"1900":13.3},"lichess":{"400":33.5,"1000":30.1,"1200":26.5,"1400":23.6,"1600":20.4,"1800":17,"2000":13.7,"2200":12.5}}},{"nume":"Dacă adversarul joacă 3…e6","moves_uci":"d2d4 g7g6 g1f3 f8g7 c1f4 e7e6 b1c3 g8e7 e2e4 e8g8 d1d2 d7d6 f4h6","move_explanations":{"5":"e6 — adversarul nu ocupă centrul cu pionii, ci pregăteşte Ce7.","6":"Cc3 — scoţi calul spre centru. Dacă adversarul nu loveşte în centru, împingi şi pionul e.","7":"Ce7 — calul iese pe e7, ca să nu închidă nebunul de pe g7.","8":"e4 — ocupi centrul cu doi pioni, pe d4 şi e4.","9":"Rocada adversarului.","10":"Dd2 — dama iese pe d2 şi se uită spre h6: de acolo, nebunul tău poate schimba nebunul de pe g7.","11":"d6 — adversarul îşi face loc în centru.","12":"Nh6 — propui schimbul nebunului de pe g7, care îi apără regele adversarului."},"final_text":"Ai un centru mare, cu pionii pe d4 şi e4, iar după schimbul nebunilor regele adversarului rămâne slăbit. Urmează rocada mare şi atacul cu pionul h.","popularitate_pe_rating":{"chesscom":{"400":12.7,"700":14.8,"1000":14.9,"1300":13.4,"1600":10.1,"1900":7.1},"lichess":{"400":9.9,"1000":12.9,"1200":14.4,"1400":14.8,"1600":13.8,"1800":10.7,"2000":6,"2200":1.7}}},{"nume":"Dacă adversarul joacă 4…Cd7","moves_uci":"d2d4 g7g6 g1f3 f8g7 c1f4 d7d6 e2e3 b8d7 h2h3 g8f6 f1e2 e8g8 e1g1 f8e8 c2c3","move_explanations":{"7":"Cd7 — adversarul scoate calul de pe b8 înaintea celui de pe g8, ca să pregătească e5.","8":"h3 — faci loc nebunului tău: dacă e atacat, se poate retrage pe h2.","9":"Cgf6 — adversarul scoate şi celălalt cal.","10":"Ne2 — scoţi nebunul şi pregăteşti rocada.","11":"Rocada adversarului.","12":"Rocada ta. Ambii regi sunt la adăpost.","13":"Te8 — tura vine pe e8 şi sprijină împingerea e5.","14":"c3 — sprijini pionul de pe d4. Dacă adversarul împinge e5, centrul tău rezistă."},"final_text":"Ai o poziţie solidă: regele e la adăpost, iar pionii de pe c3, d4 şi e3 ţin centrul. Scoate calul de pe b1 pe d2, apoi caută un loc bun pentru damă.","popularitate_pe_rating":{"chesscom":{"400":9.2,"700":9.7,"1000":10.6,"1300":12.2,"1600":15.2,"1900":19},"lichess":{"400":9.5,"1000":9.5,"1200":10.5,"1400":12,"1600":13.9,"1800":16.7,"2000":22.4,"2200":36.4}}}]$j$::jsonb
