  variante = $j$[{"nume":"Dacă adversarul joacă 2…cxd4","moves_uci":"d2d4 c7c5 c2c3 c5d4 c3d4 d7d5 g1f3 b8c6 b1c3 g8f6 c1f4","move_explanations":{"3":"cxd4 — adversarul schimbă imediat pionii din centru.","4":"cxd4 — iei înapoi cu pionul c. Ai din nou un pion pe d4, iar coloana c se deschide.","5":"d5 — adversarul pune şi el un pion în centru.","6":"Cf3 — scoţi calul spre centru.","7":"Cc6 — adversarul scoate calul şi atacă pionul de pe d4.","8":"Cc3 — scoţi şi al doilea cal, care ţinteşte d5.","9":"Cf6 — adversarul apără pionul de pe d5 cu calul.","10":"Nf4 — scoţi nebunul pe f4, ca în sistemul London."},"final_text":"Coloana c e deschisă, iar centrul e simetric. Urmează e3, apoi nebunul pe d3 sau e2 şi rocada.","popularitate_pe_rating":{"chesscom":{"400":39.4,"700":46.2,"1000":51.5,"1300":54.5,"1600":53.2,"1900":48.6},"lichess":{"400":35.2,"1000":41.3,"1200":47.6,"1400":53.3,"1600":57.1,"1800":56.6,"2000":52.1,"2200":45.4}}},{"nume":"Dacă adversarul joacă 5…Cc6","moves_uci":"d2d4 c7c5 c2c3 g8f6 g1f3 d7d5 c1f4 e7e6 e2e3 b8c6 b1d2 f8d6 f4g3 e8g8 f1d3 f8e8 f3e5","move_explanations":{"9":"Cc6 — adversarul scoate calul înainte de nebun.","10":"Cbd2 — scoţi al doilea cal pe d2, în spatele pionilor tăi.","11":"Nd6 — adversarul îşi pune nebunul în faţa celui al tău şi îţi propune schimbul.","12":"Ng3 — păstrezi nebunul pe diagonală. Dacă adversarul ia pe g3, iei cu pionul de pe h2 şi se deschide coloana h.","13":"Rocada adversarului.","14":"Nd3 — scoţi nebunul pe d3, de unde ţinteşte spre regele adversarului.","15":"Te8 — tura vine pe e8 şi pregăteşte e5.","16":"Ce5 — calul sare pe e5, în centru, unde e greu de alungat."},"final_text":"Calul de pe e5 şi nebunii de pe d3 şi g3 ţintesc spre flancul regelui. Urmează f4, ca să sprijini calul, apoi rocada.","popularitate_pe_rating":{"chesscom":{"400":38.8,"700":41.7,"1000":44.6,"1300":50.4,"1600":58.7,"1900":63.5},"lichess":{"400":37.3,"1000":39.2,"1200":42.1,"1400":44.9,"1600":50,"1800":56.9,"2000":62.5,"2200":64.7}}},{"nume"