do $$
declare n int; total int;
begin
  select count(*), coalesce(sum(jsonb_array_length(coalesce(l.variante, '[]'::jsonb))), 0) into n, total
    from public.opening_lines l join public.courses c on c.id = l.course_id
   where c.slug in ('london-system', 'kings-gambit', 'queens-gambit', 'catalan-opening', 'ruy-lopez', 'english-opening', 'kings-indian-attack', 'colle-system', 'vienna-game', 'sicilian-defense', 'french-defense', 'caro-kann-defense', 'kings-indian-defense', 'nimzo-indian-defense', 'dutch-defense', 'slav-defense', 'pirc-defense', 'scandinavian-defense', 'alekhine-defense') and l.grup is not null and l.popularitate_pe_rating ? 'lichess';
  if n <> 57 or total <> 167 then
    raise exception 'Variante: % capitole, % variante; aşteptat 57 şi 167', n, total;
  end if;
end $$;
